dmund-iv","nom":"Edmund IV","titre":"Roi d'Aubeclaire","description":"Couronne lourde, barbe grise, regard fatigué et dur."},"seraphine":{"id":"seraphine","nom":"Séraphine d'Aubeclaire","titre":"Princesse","description":"Seconde de la lignée, espiègle sous l'étiquette."},"elianne":{"id":"elianne","nom":"Sœur Elianne","titre":"Prêtresse","description":"Douce, patiente, têtue quand il s'agit de justice."},"kaya":{"id":"kaya","nom":"Kaya Lunecroc","titre":"Aventurière ourvalis, rang E","description":"Oreilles de loup argentées, franche jusqu'à la gaffe."},"vorthak":{"id":"vorthak","nom":"Vorthak","titre":"Émissaire des Cendres","description":"Démon en armure noire aux flammes violettes."},"ferrand":{"id":"ferrand","nom":"Ferrand","titre":"Marchand de reliques","description":"Sourire huileux, manteau trop beau pour son commerce."},"halvine":{"id":"halvine","nom":"Dame Halvine Corbelet","titre":"Marchande du Comptoir","description":"Petite femme vive aux lunettes rondes, tablier plein de poches, compte plus vite que son boulier."},"bram":{"id":"bram","nom":"Bram","titre":"Tavernier du Chaudron Fêlé","description":"Colosse jovial, tablier taché, cœur d'or."},"lina":{"id":"lina","nom":"Lina","titre":"Jeune tanneuse","description":"Disparue du quartier des Tanneurs."},"tobin":{"id":"tobin","nom":"Tobin","titre":"Apprenti de l'Ordre","description":"Dix-neuf ans, curieux, trop curieux."},"gareth":{"id":"gareth","nom":"Gareth","titre":"Fermier de la Combe-aux-Saules","description":"Mains calleuses, chapeau de paille."},"mentor":{"id":"mentor","nom":"Maître Orlo","titre":"Mentor d'enfance","description":"Vieux bibliothécaire bourru."},"rival":{"id":"rival","nom":"Cassian","titre":"Rival d'enfance","description":"Fils de garde, fier et rapide."},"ami-enfance":{"id":"ami-enfance","nom":"Pipa","titre":"Amie d'enfance","description":"Rieuse, intrépide, toujours une égratignure au genou."}},"scenes":{"av-ronde":{"id":"av-ronde","titre":"Aveline — La ronde de nuit","type":"individuel","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous croisez Aveline pendant sa ronde, une lanterne à la main. « Encore debout ? Les héros ne dorment jamais, c'est ça ? »"}],"effets":[],"choix":[{"texte":"« Je pourrais vous accompagner. Deux paires d'yeux valent mieux qu'une. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"accompagne"},{"texte":"« Et vous, capitaine ? Vous ne dormez jamais non plus. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"question"},{"texte":"« Ce n'est pas un peu ennuyeux, de tourner en rond toute la nuit ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-2}}],"aller":"vexee"}],"fin":false},"accompagne":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle hésite, puis hoche la tête. Vous marchez longtemps en silence. C'est un silence étonnamment agréable."},{"qui":"aveline","expression":"joie","dit":"Au détour d'une rue, elle s'arrête net devant une pâtisserie fermée, le nez presque collé à la vitre. Puis elle se reprend. « Je… vérifiais les serrures. »"}],"effets":[{"flag":"heros:secret-patisserie"}],"choix":[],"suite":"fin","fin":false},"question":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"« Pas beaucoup, non. » Elle regarde vers le nord. « Quand je ferme les yeux, je vois Valgrane. » Elle n'en dit pas plus."}],"effets":[],"choix":[],"suite":"fin","fin":false},"vexee":{"repliques":[{"qui":"aveline","expression":"colere","dit":"« C'est ce qui permet à la ville de dormir tranquille. » Elle s'éloigne d'un pas raide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-entrainement":{"id":"av-entrainement","titre":"Aveline — Leçon d'escrime","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"examen-reussi","affinite_min":{"aveline":10}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Dans la cour du château, Aveline vous lance une épée de bois. « Votre garde est catastrophique. Montrez-moi ce que vous savez faire. »"}],"effets":[],"choix":[{"texte":"Vous battre sérieusement. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Esquiver et la faire tourner en bourrique. (Agilité, difficulté 16)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher : lui jeter du sable aux yeux.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-6}}],"aller":"triche"}],"fin":false},"gagne":{"repliques":[{"qui":"aveline","expression":"surprise","dit":"Votre lame de bois s'arrête à un doigt de sa gorge. Elle vous fixe, sidérée… puis éclate de rire. Un vrai rire."},{"qui":"aveline","expression":"joie","dit":"« Encore. Demain. Même heure. » Ce n'est pas une question."}],"effets":[{"affinite":{"aveline":7},"xp":40}],"choix":[],"suite":"fin","fin":false},"perd":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous voilà sur le dos, sa lame de bois sur votre poitrine. « Pas mal. Pour un débutant. » Elle vous tend la main pour vous relever."}],"effets":[{"affinite":{"aveline":4},"xp":25}],"choix":[],"suite":"fin","fin":false},"triche":{"repliques":[{"qui":"aveline","expression":"colere","dit":"Elle crache le sable, furieuse. « Sur un champ de bataille, peut-être. Ici, c'est une leçon d'honneur. Recommencez quand vous en aurez. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-confidence":{"id":"av-confidence","titre":"Aveline — Ce qu'on ne dit à personne","type":"individuel","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"proche"}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend au fond de la taverne, devant deux chopes qu'elle n'a pas touchées. « Asseyez-vous. J'ai… quelque chose à vous dire. »"},{"qui":"aveline","expression":"tristesse","dit":"« Mon père, Gauvain de Castelroc, commandait Valgrane. On l'a accusé d'avoir ouvert les portes aux Cendres. On l'a exécuté sans procès. »"},{"qui":"aveline","expression":"neutre","dit":"« Je n'ai jamais cru à sa trahison. Mais les archives militaires de Valgrane ont été scellées… par l'Ordre. Pourquoi l'Ordre ? »"}],"effets":[],"choix":[{"texte":"« Je vous aiderai à découvrir la vérité. Je vous en fais la promesse. »","visible_si_bloque":false,"effets":[{"flag":"heros:promesse-aveline","affinite":{"aveline":8},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"promesse"},{"texte":"« Et si la vérité ne vous plaisait pas ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"prudent"}],"fin":false},"promesse":{"repliques":[{"qui":"aveline","expression":"gene","dit":"Elle vous regarde longtemps. Puis, très doucement, elle pose sa main sur la vôtre. « Merci. » Elle la retire aussitôt, écarlate."}],"effets":[],"choix":[],"suite":"fin","fin":false},"prudent":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Alors au moins, je saurai. » Elle lève sa chope. « À la vérité, quelle qu'elle soit. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"(Quête de compagnon « Le Serment brisé » : la suite au chapitre 2.)"}],"effets":[],"choix":[],"fin":true}}},"av-remparts":{"id":"av-remparts","titre":"Aveline — Les remparts au crépuscule","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"amoureuse"}},"repetable":false,"romance":true,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Le soleil se couche sur Lysmont. Aveline est assise sur le parapet, les jambes dans le vide, sans armure."},{"qui":"aveline","expression":"gene","dit":"« Je ne suis pas douée pour… ça. Les mots. » Elle fixe l'horizon. « Avec une épée, je sais toujours quoi faire. Avec vous, jamais. »"}],"effets":[],"choix":[{"texte":"Vous asseoir à côté d'elle et prendre sa main.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"},{"texte":"« Alors ne dites rien. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"}],"fin":false},"main":{"repliques":[{"qui":"aveline","expression":"joie","dit":"Elle rit doucement, nerveusement, et pose la tête sur votre épaule. Le soleil disparaît derrière les tours blanches…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"ch1-appel":{"id":"ch1-appel","titre":"L'Appel","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"pas_flag":"appel-fait"},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"aureliath","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Printemps 1012. Un cercle de lumière bleue embrase le sol du Temple du Seuil. Des chants montent, des vitraux vibrent… puis le silence."},{"qui":"narrateur","expression":"neutre","dit":"Au centre du cercle, des silhouettes se relèvent, hagardes : les invoqués. À la lisière de la lumière, d'autres jeunes gens, attirés ici par une résonance qu'ils ne savent pas nommer : les réincarnés.","si":{"origine":"reincarne"}},{"qui":"aureliath","expression":"neutre","dit":"« Bienvenue à Velmaris, [[Appelé||Appelés]]. Je suis Auréliath, Grand Prieur de l'Ordre de la Lumière Sereine. [[N'aie||N'ayez]] crainte : la Lumière [[t'a choisi||vous a choisis]]. »"},{"qui":"aureliath","expression":"neutre","dit":"« Le Souverain des Cendres s'est éveillé au nord. Le Mur d'Aube faiblit. Le royaume a besoin de héros. »"},{"qui":"aveline","expression":"neutre","dit":"Une jeune femme en armure argentée s'avance, la main sur le pommeau. « Capitaine Aveline de Castelroc. Je suis chargée de [[ta||votre]] sécurité. » Son regard s'attarde sur [[toi||vous]], méfiant."}],"effets":[],"choix":[{"texte":"« Un monde de magie ? Génial. Où est-ce qu'on signe ? » (enthousiaste)","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5},"affinite":{"aveline":2}}],"aller":"enthousiaste"},{"texte":"« Personne ne [[m'a demandé mon||nous a demandé notre]] avis. Qui a décidé de [[m'arracher à ma vie||nous arracher à nos vies]] ? » (méfiant)","visible_si_bloque":false,"effets":[{"flag":"mefiance-ordre","reputation":{"ordre":-5},"affinite":{"aveline":4}}],"aller":"mefiant"},{"texte":"« Excusez-moi, il y a des toilettes dans ce monde ? » (humour)","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"humour"}],"fin":false},"enthousiaste":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur sourit largement. « Voilà l'esprit des héros ! »"},{"qui":"aveline","expression":"neutre","dit":"Aveline soupire. « Les derniers à avoir dit ça sont enterrés sous le Mur d'Aube. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"mefiant":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le sourire du Grand Prieur se fige une fraction de seconde. « La Lumière a ses raisons. [[Tu les comprendras||Vous les comprendrez]]. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline [[te||vous]] jette un regard nouveau. Presque… approbateur."}],"effets":[],"choix":[],"suite":"question","fin":false},"humour":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un acolyte s'étrangle. Auréliath cligne des yeux."},{"qui":"aveline","expression":"joie","dit":"Aveline détourne la tête, mais [[tu l'as||vous l'avez]] vue : elle a souri. « Par ici. Et oui, il y en a. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"classe":["arcaniste","invocateur","guerisseur","barde","alchimiste"]},"question":{"qui":"aureliath","expression":"neutre","dit":"« {pseudo}. Je sens quelque chose s'éveiller en toi. Dis-moi : que sais-tu de la magie de ce monde ? »"},"reponses":[{"texte":"« Je la sens crépiter au bout de mes doigts. Le feu, le givre… ils me répondent déjà. »","si":{"classe":"arcaniste"},"effets":[{"reputation":{"ordre":3}}],"aller":"suite"},{"texte":"« Quelque chose m'accompagne depuis mon arrivée. Une présence, à mes côtés. »","si":{"classe":"invocateur"},"effets":[{"reputation":{"ordre":2}}],"aller":"suite"},{"texte":"« Je sais seulement que mes mains apaisent la douleur. Le reste, je l'apprendrai. »","si":{"classe":"guerisseur"},"effets":[{"reputation":{"ordre":4}}],"aller":"suite"},{"texte":"« La magie ? Chez moi, ça s'appelle une bonne chanson au bon moment. »","si":{"classe":"barde"},"effets":[{"affinite":{"aveline":1}}],"aller":"suite"},{"texte":"« De la magie ? Montrez-moi vos fioles, je vous dirai ce que j'en pense. »","si":{"classe":"alchimiste"},"effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Je préfère l'acier. La magie, je la laisse à ceux qui ont le temps de réciter. »","si":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"effets":[{"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Les anciens parlent du Voile et de ses dangers. Je sais qu'on ne joue pas avec. »","si":{"race":["elfe","demi-elfe"]},"effets":[{"flag":"mefiance-ordre"}],"aller":"suite"},{"texte":"« Rien du tout. Mais j'apprends vite. »","effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Assez pour me méfier de ceux qui s'en servent sur les autres sans demander. »","effets":[{"reputation":{"ordre":-3},"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Ça dépend. Elle fait aussi le café ? »","effets":[{"affinite":{"aveline":1}}],"aller":"suite"}]},"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur lève une main. Son regard [[te détaille longuement||parcourt vos visages un à un, puis s'arrête]]."}],"effets":[],"choix":[],"fin":false},"suite":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"« [[Repose-toi||Reposez-vous]]. Demain, la Couronne [[te||vous]] recevra. En attendant, la Guilde de la Rose des Vents [[t'ouvrira ses portes : tu y apprendras||vous ouvrira ses portes : vous y apprendrez]] à survivre. »"},{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, en contemplant les tours blanches de Lysmont depuis la fenêtre du temple, [[tu vois flotter devant tes yeux une fenêtre translucide : ton niveau, tes capacités… et ton don.||chacun de vous voit flotter devant ses yeux une fenêtre translucide : votre niveau, vos capacités… et votre don.]]"}],"effets":[{"flag":["appel-fait","aveline-rencontree"],"quete":{"id":"q-ch1-appel","etape":"examen"},"recruter":"aveline","journal":"L'Appel : {groupe} arrivent au Temple du Seuil. La capitaine Aveline de Castelroc est chargée de leur sécurité."}],"choix":[],"fin":true}}},"ch1-examen":{"id":"ch1-examen","titre":"L'examen de la Guilde","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"examen"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le hall de la Guilde de la Rose des Vents sent la bière, le cuir et la sueur. Des dizaines de regards se tournent vers vous."},{"qui":"rowena","expression":"neutre","dit":"« Ah. [[Un Appelé||Les Appelés]]. » Dame Rowena mâchonne sa pipe éteinte. « Ici, [[ton don ne vaut rien tant que tu n'as pas prouvé que tu sais||votre don ne vaut rien tant que vous n'avez pas prouvé que vous savez]] tenir debout. »"},{"qui":"kaya","expression":"neutre","dit":"Une jeune femme aux oreilles de loup argentées [[te||vous]] dévisage, adossée à un pilier. « Pff. [[Il a l'air tout mou||Ils ont l'air tout mous]]. Je parie dix pièces [[qu'il tombe||qu'ils tombent]] au premier coup. »"},{"qui":"kaya","expression":"neutre","dit":"Elle vous fixe un instant de plus, puis son regard s'adoucit. « …Un Ourvalis ? Hé. Bonne chance, alors. »","si":{"race":"ourvalis"}},{"qui":"rowena","expression":"neutre","dit":"« L'examen est simple : [[tu affrontes||vous affrontez]] notre golem d'entraînement. S'il [[te||vous]] met au tapis, [[reviens||revenez]] dans un an. »"}],"effets":[],"choix":[{"texte":"Entrer dans l'arène d'entraînement.","visible_si_bloque":false,"effets":[],"aller":"conseil"},{"texte":"« Kaya, c'est ça ? Je double ta mise : vingt pièces que tu perds. »","visible_si_bloque":false,"effets":[{"flag":"pari-kaya","miser":20}],"aller":"conseil"}],"fin":false},"conseil":{"parole_a":{"regle":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"question":{"qui":"rowena","expression":"neutre","dit":"Rowena pointe sa pipe vers {nom}. « Toi, {pseudo}. Ce golem fait deux fois ta taille. Tu comptes t'y prendre comment ? »"},"reponses":[{"texte":"« Je me mets devant et j'encaisse. [[Je frapperai quand il fatiguera.||Les autres frapperont pendant ce temps.]] »","si":{"classe":"gardien"},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« Je cogne fort. Et s'il tient encore debout, je recommence. »","si":{"classe":["berserker","lame-runique"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je cherche le point faible. Tout le monde en a un, même l'argile. »","si":{"classe":["ombre","archer"]},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« De loin. Très loin. Avec quelque chose qui explose. »","si":{"classe":["arcaniste","invocateur","alchimiste"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je tiens debout plus longtemps que lui.[[|| Et je garde les autres debout.]] »","si":{"classe":["guerisseur","barde"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Avec prudence. Je regarde d'abord comment il bouge. »","effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« On verra bien une fois dedans. »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"},{"texte":"« Vous n'auriez pas un golem plus petit ? »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"combat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le golem d'argile se met en marche dans un grincement."}],"effets":[],"choix":[],"combat":{"rencontre":"examen-guilde","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Pas mal. Pas mal du tout. » Elle tamponne une carte de cuivre. « Rang F. Les contrats sont au tableau. Ne mourez pas bêtement. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya rend la mise et y ajoute vingt pièces de sa poche, en grommelant. « Ouais, bon. [[Tu as||Vous avez]] de la chance. »","si":{"flag":"pari-kaya"}}],"effets":[{"gain_pari":2},{"flag":"examen-reussi","points_guilde":50,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} réussissent l'examen de la Guilde : rang F."}],"choix":[],"suite":"ellipse","fin":false},"defaite":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Bon. Le golem [[t'a laminé||vous a laminés]]. » Elle soupire. « Mais [[tu t'es relevé||vous vous êtes relevés]]. C'est ce que je cherche. Rang F, à l'essai. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya empoche les vingt pièces avec un grand sourire. « Sans rancune. »","si":{"flag":"pari-kaya"}}],"effets":[{"perte_pari":true},{"flag":"examen-reussi","points_guilde":20,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} entrent à la Guilde « à l'essai »."}],"choix":[],"suite":"ellipse","fin":false},"ellipse":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Maintenant, au travail : contrats, entraînement, premières cicatrices. Et quand vous voudrez que les mois passent, prenez une chambre au Chaudron Fêlé. Le temps ne file que si vous le décidez. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline passera souvent « par hasard » à la Guilde. Officiellement pour vous surveiller."},{"qui":"narrateur","expression":"neutre","dit":"On raconte que des lueurs étranges apparaissent parfois sous les ruines de la Crypte de la Fontaine, à l'automne. La Guilde vous y enverra en Brumaire 1013."}],"effets":[],"choix":[],"fin":true}}},"ch1-crypte":{"id":"ch1-crypte","titre":"La Crypte de la Fontaine","type":"groupe","lieu":"crypte-fontaine","decor":"crypte-entree","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"crypte"},"date_min":{"annee":1013,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'automne est là. Des paysans ont vu des lueurs violettes sous les ruines de la Crypte de la Fontaine. Rowena [[t'a||vous a]] confié l'affaire."},{"qui":"aveline","expression":"neutre","dit":"Aveline [[t'attend||vous attend]] à l'entrée, en armure complète. « Ordre du roi : je [[t'accompagne||vous accompagne]]. Et… je n'allais pas [[te laisser descendre seul||vous laisser descendre seuls]]. »"},{"qui":"narrateur","expression":"neutre","dit":"L'escalier s'enfonce dans le noir. Une odeur d'eau croupie et de vieille pierre monte des profondeurs."}],"effets":[],"choix":[{"texte":"Descendre dans la crypte.","visible_si_bloque":false,"effets":[],"aller":"avant-descente"}],"fin":false},"avant-descente":{"parole_a":{"regle":{"classe":["ombre","archer","gardien"]},"question":{"qui":"aveline","expression":"neutre","dit":"Aveline s'arrête sur la première marche et se tourne vers {nom}. « {pseudo}, c'est toi qui ouvres la marche, ou c'est moi ? »"},"reponses":[{"texte":"« Moi. Je passe devant, sans bruit. Si quelque chose bouge, je le verrai avant qu'il nous voie. »","si":{"classe":"ombre"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Moi. Mon bouclier d'abord, tout le monde derrière. »","si":{"classe":"gardien"},"effets":[{"affinite":{"aveline":3}}],"aller":"donjon"},{"texte":"« Passe devant. Je couvre depuis l'arrière, une flèche encochée. »","si":{"classe":"archer"},"effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« Un escalier sous terre ? Laisse faire un nain. »","si":{"race":"nain"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Je vois dans le noir. Je guide, tu me suis. »","si":{"race":"elfe"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Ensemble, côte à côte. »","effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Après toi, capitaine. C'est toi qui as l'armure. »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« On tire à pile ou face ? »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"crypte-fontaine","sortie":"sortie"},"fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous remontez à la surface, couverts de poussière. Dans votre sac, le sceau cendré pulse d'une lumière violette, comme un cœur."},{"qui":"aveline","expression":"colere","dit":"« Ce symbole… » Aveline pâlit. « On l'a trouvé sur les ruines de Valgrane, il y a dix ans. Le jour où mon père… » Elle se tait."}],"effets":[{"flag":"sceau-trouve","xp":60,"quete":{"id":"q-ch1-appel","etape":"lanternes"},"journal":"Dans la Crypte de la Fontaine, {groupe} découvrent un sceau cendré."}],"choix":[{"texte":"Remettre le sceau à l'Ordre, comme le veut la loi.","visible_si_bloque":false,"effets":[{"flag":"sceau-ordre","reputation":{"ordre":10}}],"aller":"ellipse"},{"texte":"Le confier à la Guilde : Rowena saura quoi en faire.","visible_si_bloque":false,"effets":[{"flag":"sceau-guilde","reputation":{"guilde":10}}],"aller":"ellipse"},{"texte":"Le garder et l'étudier vous-mêmes, en secret.","visible_si_bloque":false,"effets":[{"flag":"sceau-garde","affinite":{"aveline":2}}],"aller":"ellipse"}],"fin":false},"ellipse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'hiver approche. Le sceau ne quitte pas vos pensées. Toute la ville parle déjà de la prochaine Fête des Lanternes, le 15 Floréal 1014."}],"effets":[],"choix":[],"fin":true}}},"ch1-lanternes":{"id":"ch1-lanternes","titre":"La Nuit des Lanternes","type":"groupe","lieu":"lysmont-place","decor":"lysmont-lanternes-nuit","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"lanternes"},"date_min":{"annee":1014,"mois":2,"jour":15}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"15 Floréal 1014, Fête des Lanternes. Des milliers de lanternes de papier s'élèvent au-dessus de Lysmont, chacune portant le nom d'un disparu."},{"qui":"bram","expression":"neutre","dit":"Bram, le tavernier, distribue des brochettes en riant. « Ce soir, c'est la maison qui régale ! »","si":{"pas_flag":"mort:bram"}},{"qui":"seraphine","expression":"neutre","dit":"Sur le balcon du château, une jeune femme blonde vous fait un petit signe discret. La princesse Séraphine."},{"qui":"aveline","expression":"neutre","dit":"Aveline est là elle aussi, en civil pour une fois, une lanterne éteinte entre les doigts."},{"qui":"aveline","expression":"gene","dit":"« C'est… pour mon père. » Elle hésite, sans vous regarder. « Vous voulez bien rester un moment ? »","si":{"affinite_min":{"aveline":20}}}],"effets":[],"choix":[{"texte":"Lâcher une lanterne avec Aveline, en silence.","si":{"affinite_min":{"aveline":20}},"visible_si_bloque":false,"effets":[{"flag":"heros:lanterne-aveline","affinite":{"aveline":6}}],"aller":"lanterne"},{"texte":"Profiter de la fête : danses, musique, brochettes.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":1}}],"aller":"attaque"}],"fin":false},"lanterne":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"Vos lanternes montent côte à côte. Aveline murmure : « Il s'appelait Gauvain. Il n'était pas un traître. » Pour la première fois, sa voix tremble."},{"qui":"aveline","expression":"gene","dit":"Elle s'essuie les yeux d'un revers de main. « …Merci. N'en parlez à personne. »"}],"effets":[],"choix":[],"suite":"attaque","fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Soudain, les lanternes virent au violet. Un cri. Puis une explosion de cendres au centre de la place."},{"qui":"narrateur","expression":"neutre","dit":"Des gobelins cendrés surgissent des égouts, guidés par des cultistes. La foule panique."},{"qui":"aveline","expression":"colere","dit":"« Protégez les civils ! » hurle Aveline en dégainant."}],"effets":[],"choix":[{"texte":"Couvrir la fuite des civils, même si les cultistes s'échappent.","visible_si_bloque":false,"effets":[{"flag":"civils-proteges","reputation":{"couronne":5},"affinite":{"aveline":5}}],"aller":"combat1"},{"texte":"Foncer sur le cultiste qui dirige l'attaque, coûte que coûte.","visible_si_bloque":false,"effets":[{"flag":["heros:civils-abandonnes","cultiste-poursuivi"],"reputation":{"guilde":5}}],"aller":"combat1"}],"fin":false},"combat1":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-cultistes","victoire":"vorthak","defaite":"defaite1"},"fin":false},"defaite1":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tombez sous le nombre. Quand vous rouvrez les yeux, la garde a repoussé les gobelins… mais le Chaudron Fêlé est en flammes."}],"effets":[{"pnj_mort":"bram"}],"choix":[],"suite":"vorthak","fin":false},"vorthak":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les flammes s'ouvrent. Une silhouette en armure noire s'avance, une épée nimbée de feu violet à la main."},{"qui":"vorthak","expression":"neutre","dit":"« Alors c'est vous, les nouveaux jouets de l'Ordre. » Il rit. « Le Souverain m'a demandé de vous saluer. »"},{"qui":"vorthak","expression":"neutre","dit":"« Le sceau. Vous l'avez. Je le sens. Rendez-le-moi, et je laisse vivre cette ville une année de plus. »","si":{"flag":"sceau-garde"}}],"effets":[],"choix":[{"texte":"« Viens le chercher. »","visible_si_bloque":false,"effets":[],"aller":"combat2"},{"texte":"« Pourquoi vous attaquez Lysmont ? Qu'est-ce que vous voulez vraiment ? » (Esprit, difficulté 17)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":17,"reussite":"revelation","echec":"combat2"},"effets":[]}],"fin":false},"revelation":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Il incline la tête, amusé. « Ce que nous voulons ? Demandez à votre Grand Prieur combien coûte un Appel. Demandez-lui qui paie. »"}],"effets":[{"flag":"indice-prix-appel"}],"choix":[],"suite":"combat2","fin":false},"combat2":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-vorthak","victoire":"victoire","defaite":"defaite2"},"fin":false},"victoire":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Vorthak recule, son armure fendue. « Intéressant… très intéressant. » Il disparaît dans un tourbillon de cendres."},{"qui":"aveline","expression":"joie","dit":"Aveline s'appuie sur son épée, essoufflée, et vous regarde avec un sourire épuisé. « Vous… vous avez été incroyables. »"}],"effets":[{"reputation":{"couronne":10,"guilde":5},"affinite":{"aveline":4}}],"choix":[],"suite":"bilan","fin":false},"defaite2":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vorthak vous balaie comme des fétus de paille, puis s'en va, l'air ennuyé. « Revenez quand vous serez dignes de mon temps. »"}],"effets":[{"reputation":{"couronne":-5}}],"choix":[],"suite":"bilan","fin":false},"bilan":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, Lysmont compte ses morts. Les lanternes calcinées jonchent les pavés."},{"qui":"bram","expression":"neutre","dit":"Bram, couvert de suie, vous serre la main à vous broyer les os. « Vous avez sauvé ma taverne. Ici, vous ne paierez plus jamais une bière. »","si":{"flag":"civils-proteges","pas_flag":"mort:bram"}},{"qui":"narrateur","expression":"neutre","dit":"Le Chaudron Fêlé n'est plus que cendres. Bram n'a pas survécu.","si":{"flag":"mort:bram"}}],"effets":[{"flag":"lanternes-faites","quete":{"id":"q-ch1-appel","etape":"serment"},"journal":"Fête des Lanternes : Vorthak, émissaire des Cendres, attaque Lysmont."}],"choix":[],"fin":true}}},"ch1-serment":{"id":"ch1-serment","titre":"Le Serment","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"serment"},"date_min":{"annee":1014,"mois":10,"jour":3}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"edmund-iv","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Nivôse 1014. La salle du trône est glaciale. Le roi Edmund IV vous toise depuis son trône doré."},{"qui":"edmund-iv","expression":"neutre","dit":"« Vous avez défendu ma capitale. Bien. Mais un héros sans maître est une épée sans fourreau : dangereux. »"},{"qui":"edmund-iv","expression":"neutre","dit":"« Agenouillez-vous et jurez fidélité à la Couronne. Vous aurez titres, or, et l'honneur de mourir pour Aubeclaire. »"},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine, debout à côté du trône, serre les poings. Elle croise votre regard et secoue très légèrement la tête."},{"qui":"aveline","expression":"neutre","dit":"Aveline, au garde-à-vous, fixe un point droit devant elle. Mais ses jointures blanchissent sur son épée."}],"effets":[],"choix":[{"texte":"Jurer fidélité à la Couronne.","visible_si_bloque":false,"effets":[{"flag":"serment-couronne","reputation":{"couronne":15,"guilde":-5},"affinite":{"aveline":2}}],"aller":"jure"},{"texte":"Refuser poliment : vous resterez des aventuriers libres, fidèles à la Guilde.","visible_si_bloque":false,"effets":[{"flag":"independants","reputation":{"couronne":-10,"guilde":15}}],"aller":"refus"},{"texte":"Négocier : une alliance d'égal à égal, pas un serment de vassal. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"negociation","echec":"negociation-ratee"},"effets":[]},{"texte":"Faire semblant de jurer, en croisant les doigts dans votre dos.","visible_si_bloque":false,"effets":[{"flag":["serment-couronne","heros:parole-trahie"],"reputation":{"couronne":10}}],"aller":"faux"}],"fin":false},"jure":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Relevez-vous, chevaliers d'Aubeclaire. » Le roi sourit enfin. Séraphine détourne les yeux."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"refus":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Un silence de mort. « …Soit. La Guilde répondra de vous. Ne me décevez pas. »"},{"qui":"seraphine","expression":"neutre","dit":"En sortant, Séraphine vous rattrape dans un couloir. « C'était courageux. Ou stupide. Les deux me plaisent. »"}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"negociation":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Le roi plisse les yeux… puis éclate d'un rire bref. « Vous avez du cran. Une alliance, donc. Mais je m'en souviendrai. »"}],"effets":[{"flag":"allies-libres","reputation":{"couronne":5,"guilde":5}}],"choix":[],"suite":"epilogue","fin":false},"negociation-ratee":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Des conditions ? À MOI ? » Le roi se lève, furieux. « Hors de ma vue ! »"}],"effets":[{"flag":"independants","reputation":{"couronne":-15,"guilde":10}}],"choix":[],"suite":"epilogue","fin":false},"faux":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prononcez les mots du serment. Personne ne remarque vos doigts croisés… sauf Aveline, juste derrière vous. Son visage se ferme."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"epilogue":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, sur les remparts, vous regardez les étoiles d'un ciel qui n'est pas le vôtre."},{"qui":"aveline","expression":"neutre","dit":"« Le printemps prochain, on m'envoie à la frontière sud. » Aveline hésite. « J'aimerais… que vous veniez. » Elle rougit. « Pour la mission, évidemment. »","si":{"affinite_min":{"aveline":35}}},{"qui":"narrateur","expression":"neutre","dit":"Deux ans ont passé depuis l'Appel. Velmaris n'est plus un monde étranger : c'est le vôtre, désormais. Et il brûle déjà au nord."}],"effets":[{"xp":150,"terminer_quete":"q-ch1-appel"},{"fin_chapitre":1}],"choix":[],"fin":true}}},"sq-loups-guilde":{"id":"sq-loups-guilde","titre":"Les loups de la Combe : l'affaire","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"loups-acceptes"},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Un fermier de la Combe-aux-Saules, Gareth, perd ses moutons. Il n'a pas de quoi payer un vrai contrat, alors personne n'y va. » Rowena [[te||vous]] regarde par-dessus sa pipe. « Sauf si ça [[t'intéresse||vous intéresse]]. »"}],"effets":[],"choix":[{"texte":"« [[J'y vais||On y va]]. »","visible_si_bloque":false,"effets":[{"flag":"loups-acceptes","quete":{"id":"q-loups","etape":"ferme"}}],"aller":"accepte"}],"fin":false},"accepte":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« La ferme est au sud-ouest, à l'entrée de la Combe. Et [[reviens||revenez]] me dire comment ça s'est fini. »"}],"effets":[],"choix":[],"fin":true}}},"sq-loups-ferme":{"id":"sq-loups-ferme","titre":"Les loups de la Combe : la ferme de Gareth","type":"groupe","lieu":"combe-aux-saules","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"ferme"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"gareth","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"gareth","expression":"neutre","dit":"« Trois moutons cette semaine ! Et hier, ma petite Rose a vu des yeux jaunes à la lisière. » Gareth tord son chapeau de paille entre ses mains."},{"qui":"gareth","expression":"neutre","dit":"« Les traces partent de l'enclos vers les ronces, là-bas. Moi, je n'ose plus y aller. »"}],"effets":[{"quete":{"id":"q-loups","etape":"traces"}}],"choix":[],"fin":true}}},"sq-loups-traces":{"id":"sq-loups-traces","titre":"Les loups de la Combe : les traces","type":"groupe","lieu":"combe-lisiere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"traces"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À la lisière, la terre est retournée. Des empreintes larges comme une main… et d'autres, toutes petites, à côté."}],"effets":[],"choix":[{"texte":"Suivre les grandes empreintes.","visible_si_bloque":false,"effets":[],"aller":"grandes"},{"texte":"Regarder de plus près les petites.","visible_si_bloque":false,"effets":[{"flag":"louveteaux-vus"}],"aller":"petites"}],"fin":false},"grandes":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste est franche : elle file droit vers un énorme saule, au fond de la Combe."}],"effets":[{"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true},"petites":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des louveteaux. La meute ne chasse pas par plaisir : elle nourrit ses petits. La piste mène à un énorme saule, au fond de la Combe."}],"effets":[{"xp":10,"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true}}},"sq-loups":{"id":"sq-loups","titre":"Les loups de la Combe : le vieux saule","type":"groupe","lieu":"combe-taniere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"taniere"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une tanière s'ouvre sous les racines du vieux saule. Des grognements… et des gémissements plus aigus : des louveteaux."}],"effets":[],"choix":[{"texte":"Attaquer la meute.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Utiliser votre don pour parler à la louve. (Langue universelle)","si":{"don":"langue-universelle"},"visible_si_bloque":false,"effets":[],"aller":"parler"},{"texte":"Effrayer la meute avec du feu et du bruit pour la faire partir. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"fuite","echec":"combat"},"effets":[]}],"fin":false},"parler":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La louve vous écoute, babines retroussées. Puis, lentement, elle comprend : les fermiers, les pièges, les bois plus au sud où le gibier abonde."},{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la meute est partie. Gareth n'en croit pas ses yeux."}],"effets":[{"flag":"loups-sauves","xp":80}],"choix":[],"suite":"fin","fin":false},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Torches, cris, casseroles : la meute détale vers le sud avec ses petits. Aucun sang versé."}],"effets":[{"flag":"loups-sauves","xp":60}],"choix":[],"suite":"fin","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"loups-alpha","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La meute est décimée. Les louveteaux s'enfuient dans les fourrés."}],"effets":[],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les loups vous repoussent. Gareth vous traîne jusqu'à sa ferme et vous soigne avec une soupe épaisse. « On réessaiera. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le calme revient sur la Combe. Il reste à prévenir Gareth… et Rowena, à la Guilde."}],"effets":[{"quete":{"id":"q-loups","etape":"retour"}}],"choix":[],"fin":true}}},"sq-loups-retour":{"id":"sq-loups-retour","titre":"Les loups de la Combe : le compte rendu","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"retour"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Alors, ces loups ? »"},{"qui":"rowena","expression":"neutre","dit":"« Partis sans une goutte de sang ? » Elle hausse un sourcil. « C'est rare, ça. Et ça me plaît. »","si":{"flag":"loups-sauves"}},{"qui":"gareth","expression":"neutre","dit":"Gareth a fait le chemin jusqu'à la Guilde, son chapeau à la main. « Merci, du fond du cœur. Tenez, c'est pas grand-chose, mais c'est honnête. »"}],"effets":[{"reputation":{"guilde":3},"or":25,"points_guilde":30,"terminer_quete":"q-loups"}],"choix":[],"fin":true}}},"sq-reliques":{"id":"sq-reliques","titre":"Le marchand de reliques","type":"groupe","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-reliques","pnj":"ferrand","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ferrand","expression":"neutre","dit":"« Approchez, approchez ! Un os authentique de Saint Aldebrand, le Premier Appelé ! Il guérit les fièvres et porte chance aux aventuriers. Cent pièces seulement ! »"},{"qui":"bram","expression":"neutre","dit":"Bram lève les yeux au ciel derrière son comptoir. « Ça fait trois semaines qu'il vend des os de poulet. »","si":{"pas_flag":"mort:bram"}}],"effets":[{"quete":{"id":"q-reliques","etape":"enqueter"}}],"choix":[{"texte":"Examiner la « relique » de près. (Intelligence, difficulté 15)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":15,"reussite":"demasque","echec":"rate"},"effets":[]},{"texte":"L'acheter. On ne sait jamais.","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100,"objet":"relique-douteuse"}],"aller":"achete"},{"texte":"Aller prévenir l'Ordre : vendre de fausses reliques est un crime.","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"demasque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un os de poulet, verni et gravé à la hâte. Vous le brandissez sous le nez des clients. Rires, huées : Ferrand s'enfuit sous les quolibets."}],"effets":[{"flag":"ferrand-demasque","reputation":{"guilde":5},"xp":50}],"choix":[],"suite":"fin","fin":false},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'os a l'air… vrai ? Vous n'en êtes pas sûrs. Ferrand vous adresse un clin d'œil satisfait."}],"effets":[],"choix":[],"suite":"fin","fin":false},"achete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ferrand empoche l'or avec un sourire radieux. La relique sent vaguement le poulet rôti."}],"effets":[],"choix":[],"suite":"fin","fin":false},"ordre":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Sœur Elianne arrive en personne, le visage grave. « Ces escrocs salissent la mémoire des Appelés. Merci. » Ferrand est emmené par deux gardes."}],"effets":[{"flag":"ferrand-arrete","reputation":{"ordre":8},"xp":40}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-reliques"}],"choix":[],"fin":true}}},"sq-tanneurs-plainte":{"id":"sq-tanneurs-plainte","titre":"Les disparus des Tanneurs : la plainte","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"tanneurs-commence"},"repetable":false,"romance":false,"quete":"q-tanneurs","r