,"texte":"La foule s'amasse. Il faut une solution que les deux puissent accepter sans perdre la face.","bouton":"Proposer un accord","choix":[],"test":{"carac":"CHA","difficulte":19,"reussite":"Un jour sur deux chacun : ils se serrent la main en bougonnant.","echec":"Le ton monte, un étal se renverse : la garde disperse tout le monde."}},{"lieu":"guilde","objectif":"Revenir à la Guilde toucher la récompense.","texte":"Les deux marchands ont déjà fait porter leur paiement à la Guilde.","bouton":"Toucher la récompense","choix":[]}],"test":{"carac":"CHA","difficulte":19},"duree_jours":1,"recompenses":{"or":50,"xp":35,"points_guilde":25,"objets":[]}},"c-bandits":{"id":"c-bandits","titre":"Bandits de grand chemin","description":"Escorter une caravane jusqu'au gué de Valmont.","rang_min":"E","etapes":[{"lieu":"lysmont-place","objectif":"Rejoindre la caravane sur la place de Lysmont.","texte":"Trois chariots bâchés, des mules nerveuses, un caravanier qui regarde sans cesse par-dessus son épaule.","bouton":"Prendre la route","choix":[]},{"lieu":"gue-de-valmont","objectif":"Escorter la caravane jusqu'au gué de Valmont.","texte":"Le gué est en vue. Les berges sont hautes : l'endroit rêvé pour une embuscade.","choix":[{"texte":"Partir en éclaireur.","resultat":"Vous repérez des silhouettes couchées dans les roseaux.","effets":[]},{"texte":"Rester près des chariots.","resultat":"Vous gardez les mules calmes. Un sifflement part des roseaux.","effets":[]}]},{"lieu":"gue-de-valmont","objectif":"Repousser les bandits au gué.","texte":"« La bourse ou la vie ! » Ils sortent des roseaux, l'eau jusqu'aux genoux.","choix":[],"combat":"bandits-route"},{"lieu":"guilde","objectif":"Revenir à la Guilde toucher la récompense.","texte":"Le caravanier a laissé une lettre de remerciement et la prime convenue.","bouton":"Toucher la récompense","choix":[]}],"rencontre":"bandits-route","duree_jours":5,"recompenses":{"or":65,"xp":80,"points_guilde":35,"objets":["potion-soin-petite"]}},"c-araignees"